import React,{useEffect,useState,lazy,Suspense} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUpLeft,ArrowUpRight,Search,Menu,X,Sun,Moon,Globe,ShieldCheck,LockKeyhole,UserRound,Download,Copy,Check,MapPin,BriefcaseBusiness,ScanLine,Sparkles,Wallet,MessageCircle,ChevronDown,ExternalLink,Mail,Phone,Play,ChartNoAxesCombined,Building2,HeartHandshake,GraduationCap,Target,Info,Share2,Linkedin,Instagram,Facebook,Github,Youtube,Twitter,Link2} from 'lucide-react';
import {api,AppContext,setCSRF,type User,useApp,Button} from './lib';
import './style.css';
const Dashboard=lazy(()=>import('./Dashboard'));const Admin=lazy(()=>import('./Admin'));const Exports=lazy(()=>import('./Exports'));const QRTools=lazy(()=>import('./Exports').then(m=>({default:m.QRTools})));
const features=[{icon:Globe,ar:'اسم يعبّر عنك',en:'An address of your own',desc:'عنوان مستقل على ksa.men، يجمع هويتك المهنية في مكان واحد.',eng:'Your own ksa.men address, with your professional identity in one place.'},{icon:BriefcaseBusiness,ar:'مسيرتك، بصورة أجمل',en:'Your career, beautifully presented',desc:'موقع شخصي وسيرة ATS وبطاقات تعريف من بياناتك نفسها.',eng:'A personal website, ATS resume and identity cards from the same profile.'},{icon:ScanLine,ar:'حضورك ينتقل معك',en:'Your presence travels with you',desc:'QR وبطاقة اتصال ورابط تعارف ذكي، للمشاركة بثقة.',eng:'QR, contact cards and smart introductions for confident sharing.'},{icon:Wallet,ar:'قيمة تصنعها مشاركتك',en:'Participation that brings value',desc:'نقاط الوسط للمكافآت والإهداء وأيام الخدمات، دون قيمة نقدية.',eng:'Mid Points for rewards, gifts and service days, never cash.'},{icon:ShieldCheck,ar:'خصوصيتك تحت سيطرتك',en:'Privacy in your hands',desc:'أنت تختار بياناتك العامة. وتبقى التعديلات للمراجعة قبل النشر.',eng:'You choose what is public. Changes are reviewed before publication.'},{icon:Sparkles,ar:'تطوير مستمر لهويتك',en:'A stronger digital identity',desc:'إرشادات اكتمال الملف ورادار المعلومات المهنية ومؤشرات الجودة.',eng:'Completion guidance, professional information radar and quality insights.'}];
function App(){const[lang,setLang]=useState<'ar'|'en'>((localStorage.getItem('ksa-lang') as 'ar'|'en')||'ar');const[theme,setTheme]=useState(localStorage.getItem('ksa-theme')||'dark');const[user,setUser]=useState<User|null>(null);const[platform,setPlatform]=useState<any>(null);const[toast,setToast]=useState('');const[menu,setMenu]=useState(false);const[loading,setLoading]=useState(true);const[install,setInstall]=useState<any>(null);const[update,setUpdate]=useState<ServiceWorker|null>(null);const[error,setError]=useState('');const t=(ar:string,en:string)=>lang==='ar'?ar:en;const path=location.pathname;const sub=location.hostname.endsWith('.ksa.men')&&location.hostname!=='www.ksa.men';const season=activeSeason(platform?.season);
 const refresh=async()=>{if(sub)return;const d:any=await api('/api/auth/me');setUser(d.user);setCSRF(d.csrf||'');};
 useEffect(()=>{document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';localStorage.setItem('ksa-lang',lang);},[lang]);useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('ksa-theme',theme);},[theme]);useEffect(()=>{if(season)document.documentElement.dataset.season=season;else delete document.documentElement.dataset.season;},[season]);
 useEffect(()=>{Promise.all([api('/api/platform').then(setPlatform),refresh()]).catch(e=>setError(e.message)).finally(()=>setLoading(false));if(!sub&&'serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').then(r=>{if(r.waiting)setUpdate(r.waiting);r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)setUpdate(w);});});}).catch(()=>{});}const handler=(e:any)=>{e.preventDefault();setInstall(e);};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler);},[]);
 useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(id);}},[toast]);
 const logout=async()=>{try{await api('/api/auth/logout',{method:'POST'});navigator.serviceWorker?.controller?.postMessage('CLEAR_PRIVATE');sessionStorage.clear();await refresh();location.href='/';}catch(e:any){setToast(e.message);}};
 const ctx={user,lang,t,refresh,notify:setToast};
 let page:any;if(sub)page=<Personal/>;else if(loading)page=<div className="loader"><img src="/assets/logo.webp" alt="KSA.MEN"/><p>{t('نجهز تجربتك','Preparing your experience')}</p></div>;else if(error)page=<div className="card notice">{error}<Button onClick={()=>location.reload()}>{t('إعادة المحاولة','Try again')}</Button></div>;else if(platform&&!platform.access&&!(platform.lock.mode==='home'&&path!=='/')&&!['/auth','/privacy','/terms'].includes(path))page=<Gate platform={platform} onSuccess={()=>location.reload()}/>;else if(path==='/auth')page=<Auth/>;else if(path==='/dashboard')page=user?<Dashboard/>:<Auth/>;else if(path==='/admin')page=user&&user.role!=='user'?<Admin/>:<Auth/>;else if(path.startsWith('/export/'))page=user?<Exports/>:<Auth/>;else if(path==='/search')page=<SearchPage/>;else if(path==='/qr')page=<div className="page"><PageTitle title={t('شاركها بلمسة','Share it in a scan')} subtitle={t('أداة QR وبطاقة اتصال مجانية. دون تسجيل.','Free QR and contact cards. No account needed.')}/><QRTools/></div>;else if(path==='/radar')page=user?<Radar/>:<Auth/>;else if(path==='/about')page=<About/>;else if(path==='/features')page=<Features/>;else if(path.startsWith('/quick/'))page=<Quick/>;else if(path==='/contact')page=<Contact/>;else if(['/privacy','/terms','/blog'].includes(path))page=<Content slug={path.slice(1)}/>;else if(path==='/')page=<Home/>;else page=<div className="page"><h1>{t('الصفحة غير موجودة','Page not found')}</h1><a href="/" className="button">{t('الرئيسية','Home')}</a></div>;
 return <AppContext.Provider value={ctx}><header className="header"><a className="brand" href={sub?'https://ksa.men/':'/'}><img src="/assets/icon-192.png" alt=""/><span>KSA<span className="brand-dot">.</span>MEN</span></a><nav className={menu?'nav open':'nav'}><a href={sub?"https://ksa.men/search":"/search"}>{t('اكتشف الهويات','Discover people')}</a><a href={sub?"https://ksa.men/features":"/features"}>{t('المزايا','Features')}</a><a href={sub?"https://ksa.men/radar":"/radar"}>{t('رادار المعلومة','Radar')}</a><a href={sub?"https://ksa.men/about":"/about"}>{t('من نحن','About')}</a><a href={sub?'https://ksa.men/auth':user?'/dashboard':'/auth'} className="nav-main">{user?t('موقعي','My site'):t('أنشئ موقعك','Create your site')}<ArrowUpLeft size={16}/></a></nav><div className="header-tools"><button className="icon-button" onClick={()=>setLang(lang==='ar'?'en':'ar')} aria-label="اللغة"><Globe size={18}/><span>{lang==='ar'?'EN':'ع'}</span></button><button className="icon-button" onClick={()=>setTheme(theme==='dark'?'light':'dark')} aria-label={t('المظهر','Theme')}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button>{user&&<button className="icon-button logout" onClick={logout}>{t('خروج','Log out')}</button>}<button className="icon-button menu-button" onClick={()=>setMenu(!menu)} aria-label="القائمة">{menu?<X/>:<Menu/>}</button></div></header>
 <main><Suspense fallback={<div className="loader">{t('جارٍ التحميل','Loading')}</div>}>{page}</Suspense></main>{install&&<button className="install-float" onClick={async()=>{await install.prompt();setInstall(null);}}><Download size={17}/>{t('ثبّت التطبيق','Install app')}</button>}{!sub&&/iPad|iPhone|iPod/.test(navigator.userAgent)&&!matchMedia('(display-mode: standalone)').matches&&<details className="ios-install"><summary>{t('تثبيت التطبيق على iPhone','Install on iPhone')}</summary><p>{t('في Safari، اضغط مشاركة ثم «إضافة إلى الشاشة الرئيسية».','In Safari, tap Share, then Add to Home Screen.')}</p></details>}{update&&<div className="update-bar">{t('إصدار أحدث متاح. احفظ عملك ثم حدّث.','An update is available. Save your work before updating.')}<Button onClick={()=>{update.postMessage('SKIP_WAITING');navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});}}>{t('تحديث','Update')}</Button></div>}{toast&&<div className="toast" role="status"><Check size={18}/>{toast}</div>}{!sub&&<Sanad/>}<Footer sub={sub} platform={platform}/></AppContext.Provider>;
}
function activeSeason(value:any){const starts=Number(value?.starts_at??value?.startsAt??0),ends=Number(value?.ends_at??value?.endsAt??0),clock=Math.floor(Date.now()/1000);if(!value?.enabled||!Number.isFinite(starts)||!Number.isFinite(ends)||starts<=0||ends<starts||clock<starts||clock>ends)return '';const occasions=new Set(['eid_al_fitr','eid_al_adha','national_day','founding_day']);return occasions.has(value.occasion)?value.occasion:'';}
function Footer({sub,platform}:{sub:boolean,platform:any}){const{t,lang}=useApp();const[content,setContent]=useState<any>(null);useEffect(()=>{let current=true;if(sub){setContent(null);return;}api('/api/content/footer').then(data=>{if(current)setContent(data);}).catch(()=>{if(current)setContent(null);});return()=>{current=false;};},[sub]);const contact=platform?.contact&&typeof platform.contact==='object'?platform.contact:{};const email=typeof contact.email==='string'?contact.email:'';const whatsapp=typeof contact.whatsapp==='string'?contact.whatsapp.replace(/\D/g,''):'';const note=typeof content?.['body_'+lang]==='string'?content['body_'+lang].trim():'';return <footer className="footer"><div><a className="brand" href={sub?'https://ksa.men/':'/'}>KSA.MEN</a><p>{note||t('ظهور رقمي يليق بك','A digital presence worthy of you')}</p>{(email||whatsapp)&&<div className="footer-contact">{email&&<a href={'mailto:'+email}><Mail size={14}/>{email}</a>}{whatsapp&&<a href={'https://wa.me/'+whatsapp} target="_blank" rel="noreferrer"><Phone size={14}/>{t('تواصل عبر واتساب','WhatsApp contact')}</a>}</div>}</div><div className="footer-links"><a href={sub?'https://ksa.men/privacy':'/privacy'}>{t('سياسة الخصوصية','Privacy')}</a><a href={sub?'https://ksa.men/terms':'/terms'}>{t('سياسة الاستخدام','Terms')}</a><a href={sub?'https://ksa.men/about':'/about'}>{t('من نحن','About')}</a><a href={sub?'https://ksa.men/blog':'/blog'}>{t('المدونة','Journal')}</a><a href={sub?'https://ksa.men/admin':'/admin'}>{t('الإدارة والإشراف','Administration')}</a></div><p className="muted">© {new Date().getFullYear()} KSA.MEN</p></footer>;}
function useManagedContent(slug:string){const[data,setData]=useState<any>(null);useEffect(()=>{let active=true;api('/api/content/'+slug).then(value=>{if(active)setData(value);}).catch(()=>{});return()=>{active=false;};},[slug]);return data;}
function ManagedText({slug,fallback}:{slug:string,fallback:React.ReactNode}){const{lang}=useApp();const[data,setData]=useState<any>(null);useEffect(()=>{let current=true;api('/api/content/'+slug).then(value=>{if(current)setData(value);}).catch(()=>{if(current)setData(null);});return()=>{current=false;};},[slug]);const body=data?.['body_'+lang];if(typeof body!=='string'||!body.trim())return <>{fallback}</>;return <>{body.split(/\n\n/).filter(Boolean).map((paragraph:string,index:number)=><p key={index}>{paragraph}</p>)}</>;}
function PageTitle({title,subtitle}:{title:string,subtitle?:string}){return <div className="page-title"><div className="eyebrow">KSA.MEN</div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>;}
function Home(){const{t,lang}=useApp();const[q,setQ]=useState('');const homeCopy=useManagedContent('home');return <><section className="hero"><div className="hero-content"><div className="eyebrow"><span className="status-dot"/>{t('منصة رجال المملكة العربية السعودية','Saudi men’s digital identity platform')}</div><img className="hero-logo" src="/assets/logo.webp" alt="KSA.MEN" fetchPriority="high"/><h1>{t('ظهور رقمي','A digital presence')}<br/><span>{t('يليق بك.','worthy of you.')}</span></h1><p className="hero-description">{homeCopy?.['body_'+lang]||t('خبراتك تستحق أن تُرى. اجمع مسيرتك وهويتك المهنية في موقع خاص بك، على عنوان يحمل اسمك.','Your expertise deserves to be seen. Bring your story and professional identity together, at an address that carries your name.')}</p><form className="hero-search" action="/search"><Search/><input name="q" value={q} onChange={e=>setQ(e.target.value)} placeholder={t('ابحث بالاسم، التخصص أو المدينة','Search by name, expertise or city')}/><button aria-label={t('بحث','Search')}><ArrowUpLeft/></button></form><a className="advanced-link" href="/search?advanced=1">{t('البحث المتقدم','Advanced search')} <ChevronDown size={14}/></a><div className="hero-actions"><a className="button primary" href="/auth?register=1">{t('أنشئ موقعك واحجز اسمك المميز','Create your site & claim your name')}<ArrowUpLeft size={20}/></a><a className="button secondary" href="/features">{t('مزايا المنصة','Explore features')}</a></div><div className="hero-assurances"><span><ShieldCheck size={15}/>{t('خصوصية تتحكم بها','Privacy you control')}</span><span><Check size={15}/>{t('٣ أيام، جميع المزايا','3 days, all features')}</span><span><Check size={15}/>{t('دون بطاقة دفع','No payment card')}</span></div></div><div className="hero-side"><div className="address-orbit"><span>YOUR NAME. YOUR PRESENCE.</span><div><Globe size={35}/><strong><span>{t('اسمك','yourname')}</span>.ksa.men</strong><p>{t('عنوانك، لا مجرد صفحة أخرى.','Your address. Not just another page.')}</p></div><div className="orbit-caption"><span>01</span>{t('هوية سعودية. أثر يمتد.','Saudi identity. Lasting impact.')}</div></div></div></section><picture className="panorama"><source media="(max-width:760px)" srcSet="/assets/cover-720.webp"/><img src="/assets/cover-1600.webp" alt={t('معالم المملكة العربية السعودية','Saudi Arabian landmarks')}/></picture><section className="qr-band section"><div><span className="eyebrow">{t('خدمات QR المجانية','FREE QR TOOLS')}</span><h2>{t('اختصر المسافة','Bring people closer')}<br/>{t('بينك وبين العالم.','in a single scan.')}</h2><p>{t('حوّل رابطك أو بيانات اتصالك إلى QR، وحمّله للمشاركة والطباعة. دون إنشاء حساب.','Turn a link or your contact details into a printable, shareable QR. No account required.')}</p><a href="/qr" className="button primary">{t('أنشئ QR الآن','Create a QR')}<ScanLine size={20}/></a></div><div className="qr-art" aria-hidden="true"><ScanLine size={150} strokeWidth={.8}/><span>KSA.MEN</span></div></section><section className="section intro-section"><div className="section-heading"><span className="eyebrow">{t('أنت أكبر من سيرة ذاتية','MORE THAN A RESUME')}</span><h2>{t('مسيرة تستحق','A career that deserves')}<br/><span>{t('مساحة خاصة بها.','its own space.')}</span></h2><p>{t('من أول انطباع إلى الفرصة التالية، اجعل حضورك واضحًا، متكاملًا وقابلًا للمشاركة.','From first impression to your next opportunity, make your presence clear, complete and shareable.')}</p></div><FeatureCards/></section><section className="section purpose-banner"><HeartHandshake size={36}/><h2>{t('نؤمن بجدارتك.','We believe in your capability.')}</h2><p>{t('رأس مالنا البشري يستحق أن يعرفه العالم. هنا، تبدأ مساحة ظهورك المهني.','Our human capital deserves to be known. Your professional presence starts here.')}</p><a href="/about" className="text-link">{t('اقرأ قصتنا','Our story')}<ArrowUpLeft size={18}/></a></section></>;}
function FeatureCards(){const{t}=useApp();return <div className="feature-grid">{features.map((f,i)=><article className="feature-card" key={f.ar}><span className="feature-number">0{i+1}</span><f.icon size={28}/><h3>{t(f.ar,f.en)}</h3><p>{t(f.desc,f.eng)}</p></article>)}</div>;}
function Features(){const{t,lang}=useApp();const content=useManagedContent('features');return <div className="page"><PageTitle title={content?.['title_'+lang]||t('كل ما تحتاجه لظهور يليق بك','Everything for a presence worthy of you')} subtitle={content?.['body_'+lang]||t('هوية رقمية مستقلة. أدوات مشاركة عملية. تحكم واضح في بياناتك.','An independent identity. Practical sharing tools. Clear control of your data.')}/><FeatureCards/><section className="card trial-card"><h2>{t('ابدأ بثلاثة أيام كاملة','Start with three full days')}</h2><p>{t('جميع الخدمات متاحة خلال التجربة دون بطاقة دفع. بعدها يبقى موقعك الأساسي وQR متاحين، وتخضع الخدمات الإضافية لاستحقاقك.','All services are available during your trial, without a payment card. Your basic site and QR remain available afterward; extra services follow your entitlement.')}</p><a href="/auth?register=1" className="button primary">{t('أنشئ هويتك','Create your identity')}</a></section></div>;}
function Auth(){const{t,refresh,notify}=useApp();const[mode,setMode]=useState(new URLSearchParams(location.search).has('register')?'register':'login');const[email,setEmail]=useState('');const[name,setName]=useState('');const[phone,setPhone]=useState('');const[agree,setAgree]=useState(false);const[challenge,setChallenge]=useState('');const[code,setCode]=useState('');const[pin,setPin]=useState('');const[busy,setBusy]=useState(false);const[err,setErr]=useState('');const[quick,setQuick]=useState(false);const[verified,setVerified]=useState(false);const[showPin,setShowPin]=useState(false);
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setErr('');try{if(quick){const d:any=await api('/api/auth/quick',{method:'POST',body:JSON.stringify({pin})});setCSRF(d.csrf);await refresh();location.href='/dashboard';return;}if(!challenge){const d:any=await api('/api/auth/request',{method:'POST',body:JSON.stringify({email,name,whatsapp:phone,consent:agree,purpose:mode,referral:new URLSearchParams(location.search).get('ref')||undefined})});setChallenge(d.challenge);notify(d.message);}else{const d:any=await api('/api/auth/verify',{method:'POST',body:JSON.stringify({challenge,code,...(pin?{pin}:{})})});setCSRF(d.csrf);await refresh();setVerified(true);location.href=d.user.role==='owner'?'/admin':'/dashboard';}}catch(e:any){setErr(e.message);}finally{setBusy(false);}};
 return <div className="auth-page"><section className="auth-story"><span className="eyebrow">{t('الخطوة الأولى إلى حضورك','YOUR NEXT CHAPTER')}</span><h1>{t('اسمك. قصتك.','Your name. Your story.')}<br/><span>{t('مساحتك.','Your space.')}</span></h1><p>{t('حي الله فخرنا. نرافقك من أول خطوة، إلى موقع تفخر بمشاركته.','Welcome. We’re with you from your first step to a site you’re proud to share.')}</p><img src="/assets/cover-720.webp" alt=""/><div className="auth-benefits"><p><Check/>{t('عنوان مستقل يحمل اسمك','An independent address')}</p><p><Check/>{t('٣ أيام مجانية لجميع المزايا','3 free days with every feature')}</p><p><ShieldCheck/>{t('رمز بريد آمن، دون كلمة مرور عامة','Secure email verification')}</p></div></section><section className="auth-card card"><div className="eyebrow">KSA.MEN</div><h2>{quick?t('الدخول السريع','Quick sign-in'):challenge?t('تحقق من بريدك','Check your email'):mode==='register'?t('أنشئ موقعك','Create your site'):mode==='recover'?t('استرجاع الحساب','Recover your account'):t('عودًا مرحبًا','Welcome back')}</h2><p className="muted">{challenge?t('أدخل الرمز المرسل إلى '+email,'Enter the code sent to '+email):t('التحقق من البريد يحمي حسابك وبياناتك.','Email verification protects your account and data.')}</p><form onSubmit={submit} className="stack">{!quick&&!challenge&&<><label className="field">{t('البريد الإلكتروني','Email')}<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" dir="ltr"/></label>{mode==='register'&&<><label className="field">{t('اسمك','Your name')}<input required minLength={2} value={name} onChange={e=>setName(e.target.value)} autoComplete="name"/></label><label className="field">{t('رقم واتساب','WhatsApp')}<input required type="tel" value={phone} onChange={e=>setPhone(e.target.value)} autoComplete="tel" dir="ltr" placeholder="05xxxxxxxx"/></label><label className="check-label"><input type="checkbox" required checked={agree} onChange={e=>setAgree(e.target.checked)}/><span>{t('أوافق على','I agree to the')} <a href="/privacy" target="_blank">{t('سياسة الخصوصية','privacy policy')}</a> {t('و','and')} <a href="/terms" target="_blank">{t('سياسة الاستخدام','terms')}</a>، {t('وأقر بصحة بياناتي.','and confirm my data is accurate.')}</span></label></>}</>}{challenge&&<label className="field">{t('رمز التحقق — ٦ أرقام','Verification code — 6 digits')}<input className="otp" required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))} dir="ltr"/></label>}{(quick||(challenge&&mode==='register'))&&<label className="field">{quick?'PIN':t('اختر PIN من ٦ أرقام للجهاز الموثوق','Choose a 6-digit PIN for your trusted device')}<input required inputMode="numeric" type={showPin?'text':'password'} pattern="[0-9]{6}" maxLength={6} value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))} dir="ltr"/><button className="text-link" type="button" onClick={()=>setShowPin(!showPin)}>{t('إظهار / إخفاء','Show / hide')}</button></label>}{err&&<p className="error" role="alert">{err}</p>}<Button disabled={busy} className="primary">{busy?t('لحظة من فضلك…','One moment…'):challenge?t('تحقق وادخل','Verify & sign in'):quick?t('دخول','Sign in'):t('أرسل رمز التحقق','Send verification code')}<ArrowUpLeft size={18}/></Button></form><div className="auth-links">{challenge?<button onClick={()=>{setChallenge('');setCode('');}}>{t('إعادة إرسال الرمز','Request another code')}</button>:<><button onClick={()=>{setMode(mode==='register'?'login':'register');setQuick(false);setErr('');}}>{mode==='register'?t('لديك حساب؟ ادخل','Already a member? Sign in'):t('أول زيارة؟ أنشئ حسابك','New here? Create an account')}</button><button onClick={()=>{setMode('recover');setQuick(false);}}>{t('استرجاع الحساب','Recover account')}</button><button onClick={()=>{setQuick(!quick);setErr('');}}>{quick?t('التحقق بالبريد','Verify with email'):t('PIN على جهاز موثوق','PIN on a trusted device')}</button></>}</div></section></div>;}
function Gate({platform,onSuccess}:{platform:any,onSuccess:()=>void}){const{t}=useApp();const[p,setP]=useState(''),[error,setError]=useState('');return <div className="gate card"><img src="/assets/logo.webp" alt="KSA.MEN"/><LockKeyhole size={28}/><h1>{platform.lock.reason||t('نهيئ تجربة تليق بك','Preparing a worthy experience')}</h1><p>{platform.lock.message}</p>{platform.lock.passwordEnabled&&<form onSubmit={async e=>{e.preventDefault();try{await api('/api/gate',{method:'POST',body:JSON.stringify({password:p})});onSuccess();}catch(e:any){setError(e.message);}}}><input value={p} type="password" onChange={e=>setP(e.target.value)} placeholder={t('كلمة مرور الدخول الخاص','Private access password')}/><Button className="primary">{t('دخول','Enter')}</Button></form>}{error&&<p className="error">{error}</p>}<a href="/auth" className="text-link">{t('دخول المالك والإدارة','Owner & administration sign-in')}</a></div>;}
function SearchPage(){const{t,notify}=useApp();const[q,setQ]=useState(new URLSearchParams(location.search).get('q')||''),[city,setCity]=useState(''),[specialty,setSpecialty]=useState(''),[data,setData]=useState<any>({items:[]}),[busy,setBusy]=useState(false);const search=async()=>{setBusy(true);try{setData(await api('/api/search?'+new URLSearchParams({q,city,specialty})));}catch(e:any){notify(e.message);}finally{setBusy(false);}};useEffect(()=>{search();},[]);return <div className="page"><PageTitle title={t('خبرات تستحق أن تُعرف','Expertise worth discovering')} subtitle={t('ابحث في الهويات المنشورة التي اختار أصحابها الظهور.','Discover published profiles whose owners choose to be visible.')}/><form className="search-panel card" onSubmit={e=>{e.preventDefault();search();}}><label className="field grow">{t('الاسم، التخصص، العنوان أو المعرف','Name, expertise, address or ID')}<input value={q} onChange={e=>setQ(e.target.value)} placeholder={t('ابحث هنا…','Search here…')}/></label><label className="field">{t('المدينة','City')}<select value={city} onChange={e=>setCity(e.target.value)}><option value="">{t('كل المدن','All cities')}</option>{data.cities?.map((v:string)=><option key={v}>{v}</option>)}</select></label><label className="field">{t('التخصص','Expertise')}<select value={specialty} onChange={e=>setSpecialty(e.target.value)}><option value="">{t('كل التخصصات','All expertise')}</option>{data.specialties?.map((v:string)=><option key={v}>{v}</option>)}</select></label><Button className="primary" disabled={busy}><Search size={18}/>{t('بحث','Search')}</Button></form><div className="profile-grid">{data.items?.map((r:any)=><article className="person-card card" key={r.site}><img className="avatar" src={r.profile.photo||'/assets/icon-192.png'} alt=""/><span className="eyebrow">{r.userId}</span><h2>{r.profile.name||r.name}</h2><p>{r.profile.title}</p>{r.profile.city&&<p className="muted"><MapPin size={15}/>{r.profile.city}</p>}<span className="domain-label">{r.name}.ksa.men</span><a href={r.url} className="button primary">{t('زيارة الموقع','Visit site')}<ArrowUpLeft size={16}/></a><div className="row"><a href={'/dashboard?tab=wallet&recipient='+r.userId} className="text-link">{t('إهداء نقاط','Gift points')}</a>{r.profile.allowContact!==false&&<a href={'/contact?recipient='+r.userId} className="text-link">{t('طلب التواصل','Request contact')}</a>}</div></article>)}</div>{!busy&&!data.items?.length&&<div className="empty-state"><Search size={40}/><h2>{t('لم نجد هوية مطابقة بعد','No matching profile yet')}</h2><p>{t('جرّب اسمًا آخر، أو كن من أوائل من يصنعون حضورهم هنا.','Try another name, or be among the first to create your presence here.')}</p><a href="/auth?register=1" className="button primary">{t('أنشئ موقعك','Create your site')}</a></div>}</div>;}
function About(){const{t}=useApp();return <div className="about-page"><section className="about-hero"><span className="eyebrow">{t('لأن الجدارة تستحق أن تُرى','CAPABILITY DESERVES TO BE SEEN')}</span><h1>{t('نؤمن بالإنسان.','We believe in people.')}<br/><span>{t('ونمنح أثره مساحة.','And give their impact a place.')}</span></h1><p>{t('وراء كل خبرة رحلة. وراء كل مهارة وقت وجهد وطموح. ووراء كل اسم سعودي، رأس مال بشري جدير بأن يُعرف.','Behind every skill is a journey of effort, time and ambition. Behind every Saudi name is human capital worthy of being known.')}</p></section><picture className="panorama"><img src="/assets/cover-1600.webp" alt=""/></picture><section className="section about-message"><div><HeartHandshake size={34}/><h2>{t('ظهور رقمي يليق بك','A digital presence worthy of you')}</h2></div><div><ManagedText slug="about" fallback={<><p>{t('لم نبنِ KSA.MEN لتضيف صفحة أخرى إلى الإنترنت. بنيناها لتفتح للإنسان السعودي نافذة واضحة على العالم؛ تُظهر ما تعلّمه، وما أنجزه، وما يستطيع أن يقدّمه.','We did not build KSA.MEN to add another page to the internet. We built it to give Saudi talent a clear window to the world: what they have learned, achieved and can contribute.')}</p><p>{t('نعتني بالتفاصيل لأننا نعتني بمن يقف خلفها. نسعى إلى حضور مهني صادق لا يبالغ في المؤهلات، ولا يختزل الإنسان في مسمى، ولا يترك قيمته تضيع بين الروابط.','We care about the details because we care about the people behind them. We seek an honest professional presence that never invents qualifications, reduces a person to a title, or lets their value get lost among links.')}</p><p>{t('هذه مساحة خاصة برأس المال البشري السعودي: نساعده على تقديم نفسه بثقة، وتسويق قدراته بكرامة، ومشاركة مسيرته بصورة تليق بجدارته. أنت صاحب القصة، ونحن نهتم بأن يصل صوتها بوضوح.','This is a space for Saudi human capital: to present itself with confidence, communicate its capabilities with dignity, and share its journey in a way worthy of its capability. The story is yours. We care that it is heard clearly.')}</p></>}/></div></section><section className="section about-values">{[{icon:ShieldCheck,a:'صدق في الظهور',b:'An honest presence',c:'بيانات حقيقية، مراجعة واضحة، وخصوصية يختارها صاحبها.',d:'Real data, clear review and privacy chosen by its owner.'},{icon:HeartHandshake,a:'اهتمام بالإنسان',b:'Care for people',c:'تجربة سهلة تحترم وقتك، وأدوات تساعدك لا تعقّد عليك.',d:'An easy experience that respects your time and supports you.'},{icon:Target,a:'إيمان بالجدارة',b:'Belief in capability',c:'نمنح خبرتك مساحة ليراها الآخرون، دون وعود زائفة.',d:'We give your expertise space to be seen, without false promises.'}].map(value=><article className="card" key={value.a}><value.icon size={30}/><h3>{t(value.a,value.b)}</h3><p>{t(value.c,value.d)}</p></article>)}</section><section className="section"><div className="section-heading"><span className="eyebrow">{t('وضوح يبني الثقة','TRANSPARENCY BUILDS TRUST')}</span><h2>{t('الوثائق المرفقة','Supplied company documents')}</h2></div><div className="company-documents"><a href="/assets/company-registration.webp" target="_blank" rel="noreferrer"><img src="/assets/company-registration.webp" alt={t('شهادة السجل التجاري المرفقة','Supplied commercial registration certificate')} loading="lazy"/></a><a href="/assets/company-bank.webp" target="_blank" rel="noreferrer"><img src="/assets/company-bank.webp" alt={t('بيانات الحساب البنكي المرفقة','Supplied bank account document')} loading="lazy"/></a></div></section><section className="section purpose-banner"><h2>{t('ابدأ من اسمك. ودع مسيرتك تتحدث.','Start with your name. Let your journey speak.')}</h2><a href="/auth?register=1" className="button primary">{t('أنشئ حضورك الآن','Create your presence')}</a></section></div>;}
function Content({slug}:{slug:string}){const{lang,t}=useApp();const[data,setData]=useState<any>(null),[err,setErr]=useState('');useEffect(()=>{api('/api/content/'+slug).then(setData).catch(e=>setErr(e.message));},[slug]);return <div className="page legal-page"><PageTitle title={data?.['title_'+lang]||t(slug==='privacy'?'سياسة الخصوصية':slug==='terms'?'سياسة الاستخدام':'المدونة',slug==='privacy'?'Privacy policy':slug==='terms'?'Terms of use':'Journal')}/>{err?<p className="notice">{slug==='blog'?t('تبدأ هنا قصص الحضور المهني ومقالات تطوير الهوية.','Professional presence stories and identity guidance begin here.'):err}</p>:<article className="card prose">{(data?.['body_'+lang]||'').split(/\n\n/).map((p:string,i:number)=><p key={i}>{p}</p>)}</article>}</div>;}
function Radar(){const{t,notify}=useApp();const[data,setData]=useState<any>(null),[cat,setCat]=useState('all');useEffect(()=>{api('/api/radar').then(setData).catch(e=>notify(e.message));},[]);const items=data?.items||[];return <div className="page"><PageTitle title={t('رادار المعلومة المهنية','Professional information radar')} subtitle={t('عناوين من مصادر أصلية. آخر سبعة أيام، دون إعادة نشر المحتوى.','Headlines from original sources. The last seven days, without republishing content.')}/><div className="radar-control card"><div className="radar-symbol" aria-hidden="true"><Target size={70}/></div><div><h2>{t('معلومة أحدث. رؤية أوضح.','Fresher information. Clearer perspective.')}</h2><p>{t('التاريخ هو تاريخ النشر لدى المصدر، لا وقت الجلب.','Dates reflect the publisher’s publication time, not fetch time.')}</p><select value={cat} onChange={e=>setCat(e.target.value)}><option value="all">{t('جميع المجالات','All categories')}</option>{[...new Set(items.map((x:any)=>x.category))].map((x:any)=><option key={x} value={x}>{x}</option>)}</select></div></div><div className="radar-list">{items.filter((i:any)=>cat==='all'||i.category===cat).map((i:any)=><a className="card radar-item" key={i.id} href={i.url} target="_blank" rel="noreferrer"><div className="eyebrow">{i.category} · {i.source||i.source_name}</div><h3>{i.title}</h3><div className="row muted"><time>{new Date((i.published_at||i.publishedAt)*1000).toLocaleDateString(t('ar-SA','en-GB'))}</time><ExternalLink size={16}/></div></a>)}</div>{!items.length&&<div className="empty-state"><Target size={38}/><h3>{t('لا توجد معلومات حديثة متاحة الآن','No recent information is available now')}</h3><p>{data?.status==='error'?t('تعذر جلب المصادر حاليًا، وستعاد المحاولة.','Sources could not be fetched; they will be retried.'):t('نعرض المعلومات الموثقة المنشورة خلال سبعة أيام فقط.','Only verified items published within seven days are shown.')}</p></div>}<details className="source-details"><summary>{t('المصادر وحالة الجلب','Sources & fetch status')}</summary>{data?.sources?.map((s:any)=><p key={s.id}><a href={s.url} target="_blank" rel="noreferrer">{s.name}</a> · {s.last_error?t('تعذر الجلب','Fetch failed'):t('متصل','Connected')}</p>)}</details></div>;}
function Contact(){const{user,t,notify,lang}=useApp();const contactCopy=useManagedContent('contact');const[contact,setContact]=useState<any>(null);useEffect(()=>{api('/api/platform').then(d=>setContact(d.contact)).catch(()=>{});},[]);const recipient=new URLSearchParams(location.search).get('recipient');if(!recipient)return <div className="page"><PageTitle title={contactCopy?.['title_'+lang]||t('يسعدنا أن نسمعك','We would love to hear from you')} subtitle={contactCopy?.['body_'+lang]||t('كل رحلة تبدأ بتواصل صادق. نحن هنا لمساعدتك.','Every journey begins with an honest conversation. We are here to help.')}/><section className="card contact-card">{contact?.email&&<a className="button secondary" href={'mailto:'+contact.email}><Mail size={20}/>{contact.email}</a>}{contact?.whatsapp&&<a className="button primary" href={'https://wa.me/'+contact.whatsapp.replace(/\D/g,'')} target="_blank" rel="noreferrer"><Phone size={20}/>{t('تواصل عبر واتساب','Contact us on WhatsApp')}</a>}</section></div>;if(!user)return <Auth/>;return <div className="page"><div className="card"><MessageCircle size={30}/><h1>{t('طلب تواصل مهني','Professional contact request')}</h1><p>{t('لن تبدأ المحادثة قبل موافقة المستفيد.','The conversation starts only after the recipient accepts.')}</p><Button className="primary" onClick={async()=>{try{await api('/api/contact/request',{method:'POST',body:JSON.stringify({recipient})});notify(t('تم إرسال الطلب','Request sent'));location.href='/dashboard?tab=messages';}catch(e:any){notify(e.message);}}}>{t('إرسال طلب التواصل','Send request')}</Button></div></div>;}
function Quick(){const{t}=useApp();const[data,setData]=useState<any>(null),[err,setErr]=useState('');useEffect(()=>{api('/api/public/quick/'+location.pathname.split('/').pop()).then(setData).catch(e=>setErr(e.message));},[]);return <div className="page"><div className="card quick-card">{err?<p>{err}</p>:<><span className="eyebrow">{data?.mode==='business'?t('هوية تجارية','BUSINESS IDENTITY'):data?.mode==='professional'?t('هوية مهنية','PROFESSIONAL IDENTITY'):t('تعارف سريع','A QUICK INTRODUCTION')}</span><h1>{data?.profile?.name}</h1><p>{data?.profile?.title}</p>{data?.profile?.email&&<a href={'mailto:'+data.profile.email} className="button secondary"><Mail size={16}/>{data.profile.email}</a>}{data?.profile?.whatsapp&&<a href={'https://wa.me/'+data.profile.whatsapp.replace(/\D/g,'')} className="button primary">WhatsApp</a>}{data?.profile?.url&&<a href={data.profile.url} className="button secondary">{t('الموقع','Website')}</a>}</>}</div></div>;}
function loadPublicImage(src:string){return new Promise<HTMLImageElement>((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('image unavailable'));image.src=src;});}
function roundedCanvasRect(context:CanvasRenderingContext2D,x:number,y:number,width:number,height:number,radius:number){const r=Math.min(radius,width/2,height/2);context.beginPath();context.moveTo(x+r,y);context.arcTo(x+width,y,x+width,y+height,r);context.arcTo(x+width,y+height,x,y+height,r);context.arcTo(x,y+height,x,y,r);context.arcTo(x,y,x+width,y,r);context.closePath();}
async function brandedQr(url:string,mark:string){const qr=await import('qrcode');const dataUrl=await qr.toDataURL(url,{width:640,margin:4,errorCorrectionLevel:'H'});try{const code=await loadPublicImage(dataUrl);let avatar:HTMLImageElement;try{avatar=await loadPublicImage(mark);}catch{avatar=await loadPublicImage('/assets/icon-192.png');}const canvas=document.createElement('canvas');canvas.width=code.naturalWidth;canvas.height=code.naturalHeight;const context=canvas.getContext('2d');if(!context)return dataUrl;context.drawImage(code,0,0);const size=Math.round(canvas.width*.18),x=Math.round((canvas.width-size)/2),y=Math.round((canvas.height-size)/2),padding=Math.round(size*.14);context.save();context.fillStyle='#fff';roundedCanvasRect(context,x-padding,y-padding,size+padding*2,size+padding*2,Math.round(size*.22));context.fill();roundedCanvasRect(context,x,y,size,size,Math.round(size*.16));context.clip();context.drawImage(avatar,x,y,size,size);context.restore();return canvas.toDataURL('image/png');}catch{return dataUrl;}}
function socialDetails(value:any){const url=typeof value==='string'?value:value?.url;if(typeof url!=='string'||!url)return null;let host='';try{host=new URL(url).hostname.toLowerCase().replace(/^www\./,'');}catch{return null;}const label=typeof value==='object'&&typeof value.label==='string'&&value.label.trim()?value.label.trim():host;const Icon=host.includes('linkedin.')?Linkedin:host.includes('instagram.')?Instagram:host.includes('facebook.')?Facebook:host.includes('github.')?Github:host.includes('youtube.')||host==='youtu.be'?Youtube:host.includes('twitter.')||host==='x.com'?Twitter:Globe;return {url,label,Icon};}
function Personal(){const{t,lang,notify}=useApp();const[data,setData]=useState<any>(null),[err,setErr]=useState(''),[password,setPassword]=useState(''),[image,setImage]=useState(''),[imageAlt,setImageAlt]=useState(''),[video,setVideo]=useState(false),[qr,setQr]=useState('');const profile=data?.profile||{};const url=data?.name?'https://'+data.name+'.ksa.men':'';const load=()=>api('/api/public/profile?lang='+lang).then((result:any)=>{setData(result);if(result.site&&!result.locked)api('/api/public/event',{method:'POST',body:JSON.stringify({site:result.site,event:'visit'})}).catch(()=>{});}).catch(error=>setErr(error.message));useEffect(()=>{load();},[lang]);useEffect(()=>{let current=true;if(!url){setQr('');return;}brandedQr(url,typeof profile.photo==='string'?profile.photo:'/assets/icon-192.png').then(value=>{if(current)setQr(value);}).catch(()=>{if(current)setQr('');});return()=>{current=false;};},[url,profile.photo]);useEffect(()=>{if(!image)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')setImage('');};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[image]);if(err)return <div className="page empty-state"><h1>{t('الموقع غير متاح','Site unavailable')}</h1><p>{err}</p><a href="https://ksa.men">KSA.MEN</a></div>;if(!data)return <div className="loader">{t('جارٍ التحميل','Loading')}</div>;if(data.locked)return <div className="gate card"><img className="avatar" src={data.photo} alt=""/><LockKeyhole size={28}/><h2>{data.message||t('موقع خاص','Private site')}</h2><form onSubmit={async event=>{event.preventDefault();try{await api('/api/public/unlock',{method:'POST',body:JSON.stringify({password})});load();}catch(error:any){notify(error.message);}}}><input required type="password" value={password} onChange={event=>setPassword(event.target.value)}/><Button className="primary">{t('دخول','Enter')}</Button></form></div>;const p=data.profile||{};const videoId=typeof p.youtube==='string'?youtubeId(p.youtube):'';const track=(event:'contact'|'vcard'|'qr')=>api('/api/public/event',{method:'POST',body:JSON.stringify({site:data.site,event})}).catch(()=>{});const list=(field:string,title:string,icon:any)=>{const items=p[field];if(!items?.length)return null;const Icon=icon;return <section className="profile-section card"><h2><Icon size={21}/>{title}</h2>{items.map((item:any,index:number)=>typeof item==='string'?<span className="pill" key={index}>{item}</span>:<article className="timeline-entry" key={index}><span className="muted">{item.start||item.date||''}{item.end?' — '+item.end:''}</span><h3>{item.title||item.name||item.role}</h3><strong>{item.organization||item.institution}</strong><p>{item.description}</p></article>)}</section>;};const downloadVCard=async()=>{const module=await import('./Exports');const text=module.generateVCard(p,data.name,url);const anchor=document.createElement('a');anchor.href=URL.createObjectURL(new Blob([text],{type:'text/vcard;charset=utf-8'}));anchor.download=data.name+'.vcf';anchor.click();URL.revokeObjectURL(anchor.href);track('vcard');};return <div className="personal-page"><picture className="personal-cover"><img src={p.cover||'/assets/cover-1600.webp'} alt=""/></picture><div className="personal-body"><section className="personal-intro"><img className="personal-avatar" src={p.photo||'/assets/icon-192.png'} alt={p.name||data.name}/><div><span className="eyebrow">{data.name}.KSA.MEN · {data.userId}</span><h1>{p.name||data.name}</h1><h2>{p.title}</h2>{p.city&&<p className="muted"><MapPin size={16}/>{p.city}{p.country?'، '+p.country:''}</p>}</div><div className="personal-actions"><Button className="primary" onClick={downloadVCard}><Download size={18}/>{t('حفظ جهة الاتصال','Save contact')}</Button><Button onClick={async()=>{try{if(navigator.share)await navigator.share({title:p.name||data.name,url});else{await navigator.clipboard.writeText(url);notify(t('تم نسخ الرابط','Link copied'));}}catch{}}}><Share2 size={18}/>{t('مشاركة','Share')}</Button></div></section><div className="personal-layout"><div className="personal-main">{p.bio&&<section className="profile-section card"><span className="eyebrow">{t('نبذة','ABOUT')}</span><h2>{t('القصة وراء الاسم','The story behind the name')}</h2><p className="profile-bio">{p.bio}</p></section>}{list('experience',t('الخبرات العملية','Experience'),BriefcaseBusiness)}{list('education',t('المؤهلات التعليمية','Education'),GraduationCap)}{list('training',t('التدريب والتطوير','Training'),Target)}{list('skills',t('المهارات','Skills'),Sparkles)}{list('memberships',t('العضويات المهنية','Memberships'),Building2)}{list('languages',t('اللغات','Languages'),Globe)}{list('hobbies',t('الاهتمامات','Interests'),HeartHandshake)}{list('achievements',t('الإنجازات','Achievements'),Target)}{list('timeline',t('سجل الإنجازات','Milestones'),ChartNoAxesCombined)}{[['skillImages',t('توثيق المهارات','Skill evidence')],['workImages',t('نماذج الأعمال','Selected work')]].map(([key,title])=>p[key]?.length?<section className="profile-section card" key={key}><h2>{title}</h2><div className="gallery">{p[key].map((item:any,index:number)=>{const src=typeof item==='string'?item:item.url;return <button type="button" key={index} onClick={()=>{setImage(src);setImageAlt(title);}}><img loading="lazy" src={src} alt={title}/></button>;})}</div></section>:null)}{videoId&&<section className="profile-section card"><h2>{t('تعرّف عليّ','Meet me')}</h2>{video?<iframe className="video-frame" src={'https://www.youtube-nocookie.com/embed/'+videoId} title={t('الفيديو التعريفي','Introduction video')} allow="autoplay; encrypted-media; picture-in-picture" allowFullScreen/>:<Button className="video-button" onClick={()=>setVideo(true)}><Play size={34}/>{t('تشغيل الفيديو التعريفي','Play introduction')}</Button>}</section>}</div><aside className="personal-aside"><section className="card"><h3>{t('لنبقَ على تواصل','Let’s connect')}</h3>{p.email&&<a className="contact-line" href={'mailto:'+p.email} onClick={()=>track('contact')}><Mail size={18}/>{p.email}</a>}{p.phone&&<a className="contact-line" href={'tel:'+p.phone} onClick={()=>track('contact')}><Phone size={18}/>{p.phone}</a>}{p.whatsapp&&<a className="button primary" href={'https://wa.me/'+p.whatsapp.replace(/\D/g,'')} rel="noreferrer" onClick={()=>track('contact')}>WhatsApp</a>}{p.allowContact!==false&&<a className="button secondary" href={'https://ksa.men/contact?recipient='+data.userId} onClick={()=>track('contact')}><MessageCircle size={18}/>{t('طلب التواصل','Request contact')}</a>}{p.socials?.map((item:any,index:number)=>{const social=socialDetails(item);if(!social)return null;const Icon=social.Icon;return <a key={index} className="contact-line" href={social.url} target="_blank" rel="noreferrer" onClick={()=>track('contact')}><Icon size={17}/>{social.label}</a>;})}{p.buttons?.map((item:any,index:number)=><a className="button secondary" key={index} href={item.url} target="_blank" rel="noreferrer" onClick={()=>track('contact')}><Link2 size={16}/>{item.label||item.title}</a>)}</section><section className="card profile-qr">{qr&&<div className="profile-qr-code"><img src={qr} alt={t('رمز QR يحمل صورة الهوية','QR code with identity image')}/></div>}<p>{t('امسح لتصل إلى موقعي','Scan to visit my site')}</p>{qr&&<a download={data.name+'-qr.png'} href={qr} className="text-link" onClick={()=>track('qr')}><Download size={15}/>{t('تنزيل QR','Download QR')}</a>}</section></aside></div>{data.branding&&<div className="personal-branding"><img src="/assets/icon-192.png" alt=""/><span>{t('ظهور رقمي يليق بك','A digital presence worthy of you')}</span><a href="https://ksa.men/auth?register=1">{t('أنشئ موقعك','Create your site')}</a></div>}</div>{image&&<div className="lightbox" role="dialog" aria-modal="true" aria-label={t('معاينة الصورة','Image preview')} onClick={()=>setImage('')}><button type="button" className="icon-button" aria-label={t('إغلاق','Close')} onClick={()=>setImage('')}><X/></button><img src={image} alt={imageAlt} onClick={event=>event.stopPropagation()}/></div>}</div>;}
function youtubeId(value:string){try{const raw=/^https?:\/\//i.test(value)?value:'https://'+value;const url=new URL(raw),host=url.hostname.toLowerCase().replace(/^www\./,'');if(host==='youtu.be')return url.pathname.split('/').filter(Boolean)[0]||'';if(!['youtube.com','m.youtube.com'].includes(host))return '';if(url.pathname==='/watch')return url.searchParams.get('v')||'';const [kind,id]=url.pathname.split('/').filter(Boolean);return ['embed','shorts','live'].includes(kind)?id||'':'';}catch{return '';}}

function Sanad(){const{t}=useApp();const[hide,setHide]=useState(localStorage.getItem('ksa-sanad')==='hidden'),[open,setOpen]=useState(false),[editorStep,setEditorStep]=useState(''),[missing,setMissing]=useState(0);const path=location.pathname;useEffect(()=>{if(path!=='/dashboard'){setEditorStep('');setMissing(0);return;}const inspect=()=>{const selected=document.querySelector('.dashboard-stepper [aria-selected="true"] span')?.textContent?.trim()||'';const editor=document.querySelector('.dashboard-edit-card');const fields=Array.from(editor?.querySelectorAll('input:not([type=checkbox]), textarea')||[]) as HTMLInputElement[];setEditorStep(selected);setMissing(fields.filter(field=>!field.value.trim()).length);};inspect();const observer=new MutationObserver(inspect);observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['aria-selected']});document.addEventListener('input',inspect,true);return()=>{observer.disconnect();document.removeEventListener('input',inspect,true);};},[path]);const editorTip=/الهوية|Core identity/i.test(editorStep)?t('ابدأ بالاسم والمسمى، ثم أضف صورة واضحة وغلافًا بانوراميًا.','Start with your name and title, then add a clear portrait and panoramic cover.'):/نبذة|Introduction/i.test(editorStep)?t('اكتب نبذة صادقة توضح ما تقدمه ولماذا يهم.','Write an honest bio explaining what you offer and why it matters.'):/التواصل|Contact/i.test(editorStep)?t('اختر وسائل التواصل التي ترغب حقًا في ظهورها للزوار.','Choose only contact channels you genuinely want visitors to see.'):/الخبرات|Experience/i.test(editorStep)?t('رتّب الخبرات من الأحدث، وأضف جهة وتاريخًا قابلين للتأكيد.','List the newest experience first with verifiable organization and dates.'):/التعليم|Education/i.test(editorStep)?t('أضف المؤهل والجهة كما يظهران في سجلك الرسمي.','Add qualifications and institutions exactly as in your official record.'):/التدريب|Training/i.test(editorStep)?t('أضف برامج التطوير التي تدعم تخصصك الحالي.','Add development programs that support your current specialty.'):/المهارات|Skills/i.test(editorStep)?t('اجعل كل مهارة مستقلة، ثم أضف إثباتًا بصريًا عند توفره.','Keep each skill separate, then add visual evidence when available.'):/العضويات|Memberships/i.test(editorStep)?t('اذكر العضويات المهنية النشطة والجهة المانحة لها.','List active professional memberships and their issuing body.'):/اللغات|Languages/i.test(editorStep)?t('اكتب اللغات التي تستطيع استخدامها مهنيًا بثقة.','List languages you can use professionally with confidence.'):/الهوايات|Hobbies/i.test(editorStep)?t('اختر اهتمامات تضيف بعدًا حقيقيًا لهويتك.','Choose interests that add a genuine dimension to your identity.'):/الإنجازات|Achievements/i.test(editorStep)?t('ركّز على إنجازات قابلة للتأكيد وتظهر أثر عملك.','Focus on verifiable achievements that show your impact.'):/السجل الزمني|Timeline/i.test(editorStep)?t('رتّب المحطات المهنية زمنيًا ليصبح أثر مسيرتك واضحًا.','Order milestones chronologically so your journey reads clearly.'):/إثبات المهارات|Skill evidence/i.test(editorStep)?t('حتى ثلاث صور مختارة بعناية تكفي لإثبات مهاراتك.','Up to three carefully chosen images can substantiate your skills.'):/نماذج الأعمال|Work samples/i.test(editorStep)?t('اختر حتى أربعة نماذج تمثل مستوى عملك الحالي.','Choose up to four samples that represent your current standard.'):/الفيديو|Introduction video/i.test(editorStep)?t('استخدم رابط YouTube تعريفيًا واضحًا؛ لن يُحمّل قبل تفاعل الزائر.','Use a clear YouTube introduction; it will not load before visitor interaction.'):/الروابط الاجتماعية|Social links/i.test(editorStep)?t('استخدم روابط موثوقة تعزز حضورك المهني.','Use trusted links that strengthen your professional presence.'):/الأزرار|Custom buttons/i.test(editorStep)?t('اجعل كل زر يقود إلى خطوة مفيدة وواضحة للزائر.','Make every button lead to a useful, clear next step.'):/الخصوصية|Privacy/i.test(editorStep)?t('راجع الحقول المخفية قبل الإرسال؛ الإخفاء يمنعها من الموقع والبحث والتصدير العام.','Review hidden fields before submitting; hidden data stays out of the site, search, and public exports.'):'';const tip=path==='/auth'?t('اختَر بريدًا تستخدمه فعلًا. رمز التحقق يثبت ملكيتك، وPIN يعمل على الجهاز الموثوق فقط.','Use an email you own. Verification proves ownership; PIN works only on a trusted device.'):path==='/dashboard'?(editorTip||t('ابدأ بالهوية الأساسية، ثم أكمل ما ينقص قبل إرسال لقطة المراجعة.','Start with your core identity, then complete what is missing before submitting a review snapshot.'))+(missing?t(` لديك ${missing} حقلًا فارغًا في الخطوة الحالية.`,` You have ${missing} empty field(s) in this step.`):t(' الخطوة الحالية مكتملة حقولًا؛ راجع دقتها قبل الحفظ.',' This step has no empty fields; review accuracy before saving.')):t('اختر اسمًا يعبر عنك. اجمع خبراتك وروابطك في موقع واحد، ثم شاركه بثقة.','Choose a name that represents you. Bring your experience and links together, then share confidently.');if(hide)return <button className="sanad-text" onClick={()=>{setHide(false);localStorage.removeItem('ksa-sanad');setOpen(true);}}><Info size={16}/><span>{tip}</span></button>;return <aside className={'sanad '+(open?'expanded':'')}><button className="sanad-toggle" onClick={()=>setOpen(!open)} aria-label="سند"><img src="/assets/sanad.webp" alt="سند — شخصية إرشادية"/>{open?<X size={16}/>:<span>{t('معك سند','Sanad is here')}</span>}</button>{open&&<div className="sanad-card"><button className="sanad-hide" onClick={()=>{setHide(true);localStorage.setItem('ksa-sanad','hidden');}}>{t('إخفاء','Hide')}</button><strong>{t('حي الله فخرنا، احتزم، معاك لين تخلص موقعك','Welcome, we’re with you until your site is ready')}</strong><p>{tip}</p></div>}</aside>;}
createRoot(document.getElementById('root')!).render(<App/>);
